        for (int s = 1; s <= n - i; s++) putchar(' ');
        for (int j = 1; j <= 2 * i - 1; j++) putchar('*');
        putchar('\n');
    }
    for (int i = n - 1; i >= 1; i--) {
        for (int s = 1; s <= n - i; s++) putchar(' ');
        for (int j = 1; j <= 2 * i - 1; j++) putchar('*');
        putchar('\n');
    }
